from AlgorithmImports import *
import math


class ExactStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.required_symbols = [
            self.spy,
            self.aapl,
            self.ibm,
            self.bac,
            self.aig
        ]

        self.spy_sma = self.SMA(
            self.spy,
            100,
            Resolution.Daily
        )

        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(100, Resolution.Daily)

        self.lots = {
            "A": 0,
            "B": 0
        }

        self.pending_orders = {}

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_spy_sma_ready = False

        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.spy_cross_up = False
        self.spy_cross_down = False

    def OnData(self, data):
        self._update_market_state(data)
        self._apply_splits(data)

        if self.IsWarmingUp:
            return

        if not all(symbol in data.Bars for symbol in self.required_symbols):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_lot_was_nonempty = self.lots["A"] > 0
        aapl_lot_was_nonempty = self.lots["B"] > 0

        if (
            spy_lot_was_nonempty
            and not self._has_pending_order("A")
            and self.spy_cross_down
        ):
            self._submit_order(
                "A",
                self.spy,
                -self.lots["A"],
                "sell",
                "Strategy A sell"
            )

        if (
            aapl_lot_was_nonempty
            and not self._has_pending_order("B")
            and self.aapl_rsi.Current.Value > 60
        ):
            self._submit_order(
                "B",
                self.aapl,
                -self.lots["B"],
                "sell",
                "Strategy B sell"
            )

        if (
            not spy_lot_was_nonempty
            and not self._has_pending_order("A")
            and self.spy_cross_up
        ):
            spy_close = float(data.Bars[self.spy].Close)
            total_value = float(self.Portfolio.TotalPortfolioValue)
            quantity = int(math.floor((0.40 * total_value) / spy_close))

            if quantity > 0:
                self._submit_order(
                    "A",
                    self.spy,
                    quantity,
                    "buy",
                    "Strategy A buy"
                )

        if (
            not aapl_lot_was_nonempty
            and not self._has_pending_order("B")
            and self.aapl_red_streak >= 3
        ):
            aapl_close = float(data.Bars[self.aapl].Close)

            if float(self.Portfolio.Cash) >= 20000.0:
                quantity = int(math.floor(20000.0 / aapl_close))

                if quantity > 0:
                    self._submit_order(
                        "B",
                        self.aapl,
                        quantity,
                        "buy",
                        "Strategy B buy"
                    )

    def _update_market_state(self, data):
        self.spy_cross_up = False
        self.spy_cross_down = False

        if self.spy in data.Bars:
            spy_close = float(data.Bars[self.spy].Close)
            current_spy_sma = float(self.spy_sma.Current.Value)
            current_sma_ready = self.spy_sma.IsReady

            if (
                self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_sma_ready
                and current_sma_ready
            ):
                self.spy_cross_up = (
                    self.previous_spy_close <= self.previous_spy_sma
                    and spy_close > current_spy_sma
                )

                self.spy_cross_down = (
                    self.previous_spy_close >= self.previous_spy_sma
                    and spy_close < current_spy_sma
                )

            self.previous_spy_close = spy_close
            self.previous_spy_sma = current_spy_sma
            self.previous_spy_sma_ready = current_sma_ready

        if self.aapl in data.Bars:
            aapl_close = float(data.Bars[self.aapl].Close)

            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.aapl_previous_close = aapl_close

    def _apply_splits(self, data):
        if self.spy in data.Splits:
            split_factor = float(data.Splits[self.spy].SplitFactor)
            self.lots["A"] = int(round(self.lots["A"] * split_factor))

        if self.aapl in data.Splits:
            split_factor = float(data.Splits[self.aapl].SplitFactor)
            self.lots["B"] = int(round(self.lots["B"] * split_factor))

    def _has_pending_order(self, strategy):
        return any(
            record["strategy"] == strategy
            for record in self.pending_orders.values()
        )

    def _submit_order(self, strategy, symbol, quantity, action, tag):
        if quantity == 0:
            return

        ticket = self.MarketOrder(symbol, quantity, tag=tag)

        if ticket is None or ticket.OrderId == 0:
            return

        order_id = ticket.OrderId
        self.pending_orders[order_id] = {
            "strategy": strategy,
            "action": action
        }

        if ticket.Status == OrderStatus.Filled and order_id in self.pending_orders:
            self._apply_fill(
                strategy,
                action,
                ticket.Quantity
            )
            del self.pending_orders[order_id]
        elif ticket.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            del self.pending_orders[order_id]

    def _apply_fill(self, strategy, action, fill_quantity):
        quantity = abs(int(fill_quantity))

        if action == "buy":
            self.lots[strategy] += quantity
        else:
            self.lots[strategy] = max(0, self.lots[strategy] - quantity)

    def OnOrderEvent(self, order_event):
        order_id = order_event.OrderId

        if order_id not in self.pending_orders:
            return

        record = self.pending_orders[order_id]
        status = order_event.Status

        if status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            self._apply_fill(
                record["strategy"],
                record["action"],
                order_event.FillQuantity
            )

        if status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            del self.pending_orders[order_id]
