from AlgorithmImports import *
import math


class ParallelTwoSlotAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.SetWarmUp(100, Resolution.Daily)

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.strategy_a_pending = False
        self.strategy_b_pending = False

    def OnData(self, data):
        bars = data.Bars

        spy_bar = bars[self.spy] if self.spy in bars else None
        aapl_bar = bars[self.aapl] if self.aapl in bars else None

        previous_spy_close = self.previous_spy_close
        previous_spy_sma = self.previous_spy_sma
        previous_aapl_close = self.previous_aapl_close

        if spy_bar is not None:
            self.spy_sma.Update(
                IndicatorDataPoint(self.spy, spy_bar.EndTime, spy_bar.Close)
            )

        if aapl_bar is not None:
            self.aapl_rsi.Update(
                IndicatorDataPoint(self.aapl, aapl_bar.EndTime, aapl_bar.Close)
            )

            if previous_aapl_close is not None:
                if aapl_bar.Close < previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

        all_bars_present = all(
            symbol in bars
            for symbol in (self.spy, self.aapl, self.ibm, self.bac, self.aig)
        )

        if self.IsWarmingUp or not all_bars_present:
            self._record_previous_state(spy_bar, aapl_bar)
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            self._record_previous_state(spy_bar, aapl_bar)
            return

        current_spy_sma = float(self.spy_sma.Current.Value)
        current_spy_close = float(spy_bar.Close)

        upward_sma_cross = (
            previous_spy_close is not None
            and previous_spy_sma is not None
            and float(previous_spy_close) <= float(previous_spy_sma)
            and current_spy_close > current_spy_sma
        )

        downward_sma_cross = (
            previous_spy_close is not None
            and previous_spy_sma is not None
            and float(previous_spy_close) >= float(previous_spy_sma)
            and current_spy_close < current_spy_sma
        )

        aapl_rsi_above_60 = float(self.aapl_rsi.Current.Value) > 60.0

        # Evaluate sells before buys.
        if (
            self.strategy_a_lot > 0
            and not self.strategy_a_pending
            and downward_sma_cross
        ):
            self._submit_market_order(
                "A",
                self.spy,
                -self.strategy_a_lot,
                "Strategy A Sell"
            )

        if (
            self.strategy_b_lot > 0
            and not self.strategy_b_pending
            and aapl_rsi_above_60
        ):
            self._submit_market_order(
                "B",
                self.aapl,
                -self.strategy_b_lot,
                "Strategy B Sell"
            )

        if (
            self.strategy_a_lot == 0
            and not self.strategy_a_pending
            and upward_sma_cross
            and current_spy_close > 0
        ):
            target_value = float(self.Portfolio.TotalPortfolioValue) * 0.40
            quantity = int(math.floor(target_value / current_spy_close))

            if quantity > 0:
                self._submit_market_order(
                    "A",
                    self.spy,
                    quantity,
                    "Strategy A Buy"
                )

        if (
            self.strategy_b_lot == 0
            and not self.strategy_b_pending
            and self.aapl_red_streak >= 3
            and float(aapl_bar.Close) > 0
            and float(self.Portfolio.Cash) >= 20000.0
        ):
            quantity = int(math.floor(20000.0 / float(aapl_bar.Close)))

            if quantity > 0:
                self._submit_market_order(
                    "B",
                    self.aapl,
                    quantity,
                    "Strategy B Buy"
                )

        self._record_previous_state(spy_bar, aapl_bar)

    def _record_previous_state(self, spy_bar, aapl_bar):
        if spy_bar is not None:
            self.previous_spy_close = spy_bar.Close
            if self.spy_sma.IsReady:
                self.previous_spy_sma = self.spy_sma.Current.Value

        if aapl_bar is not None:
            self.previous_aapl_close = aapl_bar.Close

    def _submit_market_order(self, strategy, symbol, quantity, tag):
        if strategy == "A":
            self.strategy_a_pending = True
        else:
            self.strategy_b_pending = True

        ticket = self.MarketOrder(symbol, quantity, tag=tag)

        if ticket is None or ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            if strategy == "A":
                self.strategy_a_pending = False
            else:
                self.strategy_b_pending = False

    def OnOrderEvent(self, order_event):
        order = self.Transactions.GetOrderById(order_event.OrderId)

        if order is None:
            return

        tag = order.Tag

        if order_event.Status in (
            OrderStatus.PartiallyFilled,
            OrderStatus.Filled,
        ):
            fill_quantity = int(order_event.FillQuantity)

            if tag == "Strategy A Buy":
                self.strategy_a_lot += fill_quantity
            elif tag == "Strategy A Sell":
                self.strategy_a_lot = max(
                    0,
                    self.strategy_a_lot + fill_quantity
                )
            elif tag == "Strategy B Buy":
                self.strategy_b_lot += fill_quantity
            elif tag == "Strategy B Sell":
                self.strategy_b_lot = max(
                    0,
                    self.strategy_b_lot + fill_quantity
                )

        if tag.startswith("Strategy A"):
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.strategy_a_pending = False

        elif tag.startswith("Strategy B"):
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.strategy_b_pending = False
